export const APACHE_CONF =
  '# This is the main Apache server configuration file.  It contains the\n# configuration directives that give the server its instructions.\n# See http://httpd.apache.org/docs/2.4/ for detailed information about\n# the directives and /usr/share/doc/apache2/README.Debian about Debian specific\n# hints.\n#\n#\n# Summary of how the Apache 2 configuration works in Debian:\n# The Apache 2 web server configuration in Debian is quite different to\n# upstream\'s suggested way to configure the web server. This is because Debian\'s\n# default Apache2 installation attempts to make adding and removing modules,\n# virtual hosts, and extra configuration directives as flexible as possible, in\n# order to make automating the changes and administering the server as easy as\n# possible.\n\n# It is split into several files forming the configuration hierarchy outlined\n# below, all located in the /etc/apache2/ directory:\n#\n#\t/etc/apache2/\n#\t|-- apache2.conf\n#\t|\t`--  ports.conf\n#\t|-- mods-enabled\n#\t|\t|-- *.load\n#\t|\t`-- *.conf\n#\t|-- conf-enabled\n#\t|\t`-- *.conf\n# \t`-- sites-enabled\n#\t \t`-- *.conf\n#\n#\n# * apache2.conf is the main configuration file (this file). It puts the pieces\n#   together by including all remaining configuration files when starting up the\n#   web server.\n#\n# * ports.conf is always included from the main configuration file. It is\n#   supposed to determine listening ports for incoming connections which can be\n#   customized anytime.\n#\n# * Configuration files in the mods-enabled/, conf-enabled/ and sites-enabled/\n#   directories contain particular configuration snippets which manage modules,\n#   global configuration fragments, or virtual host configurations,\n#   respectively.\n#\n#   They are activated by symlinking available configuration files from their\n#   respective *-available/ counterparts. These should be managed by using our\n#   helpers a2enmod/a2dismod, a2ensite/a2dissite and a2enconf/a2disconf. See\n#   their respective man pages for detailed information.\n#\n# * The binary is called apache2. Due to the use of environment variables, in\n#   the default configuration, apache2 needs to be started/stopped with\n#   /etc/init.d/apache2 or apache2ctl. Calling /usr/bin/apache2 directly will not\n#   work with the default configuration.\n\n\n# Global configuration\n#\n\n#\n# ServerRoot: The top of the directory tree under which the server\'s\n# configuration, error, and log files are kept.\n#\n# NOTE!  If you intend to place this on an NFS (or otherwise network)\n# mounted filesystem then please read the Mutex documentation (available\n# at <URL:http://httpd.apache.org/docs/2.4/mod/core.html#mutex>);\n# you will save yourself a lot of trouble.\n#\n# Do NOT add a slash at the end of the directory path.\n#\n#ServerRoot "/etc/apache2"\n\n#\n# The accept serialization lock file MUST BE STORED ON A LOCAL DISK.\n#\n#Mutex file:${APACHE_LOCK_DIR} default\n\n#\n# The directory where shm and other runtime files will be stored.\n#\n\nDefaultRuntimeDir ${APACHE_RUN_DIR}\n\n#\n# PidFile: The file in which the server should record its process\n# identification number when it starts.\n# This needs to be set in /etc/apache2/envvars\n#\nPidFile ${APACHE_PID_FILE}\n\n#\n# Timeout: The number of seconds before receives and sends time out.\n#\nTimeout 300\n\n#\n# KeepAlive: Whether or not to allow persistent connections (more than\n# one request per connection). Set to "Off" to deactivate.\n#\nKeepAlive On\n\n#\n# MaxKeepAliveRequests: The maximum number of requests to allow\n# during a persistent connection. Set to 0 to allow an unlimited amount.\n# We recommend you leave this number high, for maximum performance.\n#\nMaxKeepAliveRequests 100\n\n#\n# KeepAliveTimeout: Number of seconds to wait for the next request from the\n# same client on the same connection.\n#\nKeepAliveTimeout 5\n\n\n# These need to be set in /etc/apache2/envvars\nUser ${APACHE_RUN_USER}\nGroup ${APACHE_RUN_GROUP}\n\n#\n# HostnameLookups: Log the names of clients or just their IP addresses\n# e.g., www.apache.org (on) or 204.62.129.132 (off).\n# The default is off because it\'d be overall better for the net if people\n# had to knowingly turn this feature on, since enabling it means that\n# each client request will result in AT LEAST one lookup request to the\n# nameserver.\n#\nHostnameLookups Off\n\n# ErrorLog: The location of the error log file.\n# If you do not specify an ErrorLog directive within a <VirtualHost>\n# container, error messages relating to that virtual host will be\n# logged here.  If you *do* define an error logfile for a <VirtualHost>\n# container, that host\'s errors will be logged there and not here.\n#\nErrorLog ${APACHE_LOG_DIR}/error.log\n\n#\n# LogLevel: Control the severity of messages logged to the error_log.\n# Available values: trace8, ..., trace1, debug, info, notice, warn,\n# error, crit, alert, emerg.\n# It is also possible to configure the log level for particular modules, e.g.\n# "LogLevel info ssl:warn"\n#\nLogLevel warn\n\n# Include module configuration:\nIncludeOptional mods-enabled/*.load\nIncludeOptional mods-enabled/*.conf\n\n# Include list of ports to listen on\nInclude ports.conf\n\n\n# Sets the default security model of the Apache2 HTTPD server. It does\n# not allow access to the root filesystem outside of /usr/share and /var/www.\n# The former is used by web applications packaged in Debian,\n# the latter may be used for local directories served by the web server. If\n# your system is serving content from a sub-directory in /srv you must allow\n# access here, or in any related virtual host.\n<Directory />\n\tOptions FollowSymLinks\n\tAllowOverride None\n\tRequire all denied\n</Directory>\n\n<Directory /usr/share>\n\tAllowOverride None\n\tRequire all granted\n</Directory>\n\n<Directory /var/www/>\n\tOptions Indexes FollowSymLinks\n\tAllowOverride None\n\tRequire all granted\n</Directory>\n\n#<Directory /srv/>\n#\tOptions Indexes FollowSymLinks\n#\tAllowOverride None\n#\tRequire all granted\n#</Directory>\n\n\n\n\n# AccessFileName: The name of the file to look for in each directory\n# for additional configuration directives.  See also the AllowOverride\n# directive.\n#\nAccessFileName .htaccess\n\n#\n# The following lines prevent .htaccess and .htpasswd files from being\n# viewed by Web clients.\n#\n<FilesMatch "^\\.ht">\n\tRequire all denied\n</FilesMatch>\n\n\n#\n# The following directives define some format nicknames for use with\n# a CustomLog directive.\n#\n# These deviate from the Common Log Format definitions in that they use %O\n# (the actual bytes sent including headers) instead of %b (the size of the\n# requested file), because the latter makes it impossible to detect partial\n# requests.\n#\n# Note that the use of %{X-Forwarded-For}i instead of %h is not recommended.\n# Use mod_remoteip instead.\n#\nLogFormat "%v:%p %h %l %u %t \\"%r\\" %>s %O \\"%{Referer}i\\" \\"%{User-Agent}i\\"" vhost_combined\nLogFormat "%h %l %u %t \\"%r\\" %>s %O \\"%{Referer}i\\" \\"%{User-Agent}i\\"" combined\nLogFormat "%h %l %u %t \\"%r\\" %>s %O" common\nLogFormat "%{Referer}i -> %U" referer\nLogFormat "%{User-agent}i" agent\n\n# Include of directories ignores editors\' and dpkg\'s backup files,\n# see README.Debian for details.\n\n# Include generic snippets of statements\nIncludeOptional conf-enabled/*.conf\n\n# Include the virtual host configurations:\nIncludeOptional sites-enabled/*.conf\n'

export const APACHE_PORTS =
  '# If you just change the port or add more ports here, you will likely also\n# have to change the VirtualHost statement in\n# /etc/apache2/sites-enabled/000-default.conf\n\nListen 80\n\n<IfModule ssl_module>\n\tListen 443\n</IfModule>\n\n<IfModule mod_gnutls.c>\n\tListen 443\n</IfModule>\n'

export const APACHE_ENVVARS =
  "# envvars - default environment variables for apache2ctl\n\n# this won't be correct after changing uid\nunset HOME\n\n# for supporting multiple apache2 instances\nif [ \"${APACHE_CONFDIR##/etc/apache2-}\" != \"${APACHE_CONFDIR}\" ] ; then\n\tSUFFIX=\"-${APACHE_CONFDIR##/etc/apache2-}\"\nelse\n\tSUFFIX=\nfi\n\n# Since there is no sane way to get the parsed apache2 config in scripts, some\n# settings are defined via environment variables and then used in apache2ctl,\n# /etc/init.d/apache2, /etc/logrotate.d/apache2, etc.\nexport APACHE_RUN_USER=www-data\nexport APACHE_RUN_GROUP=www-data\n# temporary state file location. This might be changed to /run in Wheezy+1\nexport APACHE_PID_FILE=/var/run/apache2$SUFFIX/apache2.pid\nexport APACHE_RUN_DIR=/var/run/apache2$SUFFIX\nexport APACHE_LOCK_DIR=/var/lock/apache2$SUFFIX\n# Only /var/log/apache2 is handled by /etc/logrotate.d/apache2.\nexport APACHE_LOG_DIR=/var/log/apache2$SUFFIX\n\n## The locale used by some modules like mod_dav\nexport LANG=C\n## Uncomment the following line to use the system default locale instead:\n#. /etc/default/locale\n\nexport LANG\n\n## The command to get the status for 'apache2ctl status'.\n## Some packages providing 'www-browser' need '--dump' instead of '-dump'.\n#export APACHE_LYNX='www-browser -dump'\n\n## If you need a higher file descriptor limit, uncomment and adjust the\n## following line (default is 8192):\n#APACHE_ULIMIT_MAX_FILES='ulimit -n 65536'\n\n## If you would like to pass arguments to the web server, add them below\n## to the APACHE_ARGUMENTS environment.\n#export APACHE_ARGUMENTS=''\n\n## Enable the debug mode for maintainer scripts.\n## This will produce a verbose output on package installations of web server modules and web application\n## installations which interact with Apache\n#export APACHE2_MAINTSCRIPT_DEBUG=1\n"

export const APACHE_SITE_DEFAULT =
  '<VirtualHost *:80>\n\t# The ServerName directive sets the request scheme, hostname and port that\n\t# the server uses to identify itself. This is used when creating\n\t# redirection URLs. In the context of virtual hosts, the ServerName\n\t# specifies what hostname must appear in the request\'s Host: header to\n\t# match this virtual host. For the default virtual host (this file) this\n\t# value is not decisive as it is used as a last resort host regardless.\n\t# However, you must set it for any further virtual host explicitly.\n\t#ServerName www.example.com\n\n\tServerAdmin webmaster@localhost\n\tDocumentRoot /var/www/html\n\n\t# Available loglevels: trace8, ..., trace1, debug, info, notice, warn,\n\t# error, crit, alert, emerg.\n\t# It is also possible to configure the loglevel for particular\n\t# modules, e.g.\n\t#LogLevel info ssl:warn\n\n\tErrorLog ${APACHE_LOG_DIR}/error.log\n\tCustomLog ${APACHE_LOG_DIR}/access.log combined\n\n\t# For most configuration files from conf-available/, which are\n\t# enabled or disabled at a global level, it is possible to\n\t# include a line for only one particular virtual host. For example the\n\t# following line enables the CGI configuration for this host only\n\t# after it has been globally disabled with "a2disconf".\n\t#Include conf-available/serve-cgi-bin.conf\n</VirtualHost>\n'

export const APACHE_SITE_SSL =
  '<VirtualHost *:443>\n\tServerAdmin webmaster@localhost\n\n\tDocumentRoot /var/www/html\n\n\t# Available loglevels: trace8, ..., trace1, debug, info, notice, warn,\n\t# error, crit, alert, emerg.\n\t# It is also possible to configure the loglevel for particular\n\t# modules, e.g.\n\t#LogLevel info ssl:warn\n\n\tErrorLog ${APACHE_LOG_DIR}/error.log\n\tCustomLog ${APACHE_LOG_DIR}/access.log combined\n\n\t# For most configuration files from conf-available/, which are\n\t# enabled or disabled at a global level, it is possible to\n\t# include a line for only one particular virtual host. For example the\n\t# following line enables the CGI configuration for this host only\n\t# after it has been globally disabled with "a2disconf".\n\t#Include conf-available/serve-cgi-bin.conf\n\n\t#   SSL Engine Switch:\n\t#   Enable/Disable SSL for this virtual host.\n\tSSLEngine on\n\n\t#   A self-signed (snakeoil) certificate can be created by installing\n\t#   the ssl-cert package. See\n\t#   /usr/share/doc/apache2/README.Debian.gz for more info.\n\t#   If both key and certificate are stored in the same file, only the\n\t#   SSLCertificateFile directive is needed.\n\tSSLCertificateFile      /etc/ssl/certs/ssl-cert-snakeoil.pem\n\tSSLCertificateKeyFile   /etc/ssl/private/ssl-cert-snakeoil.key\n\n\t#   Server Certificate Chain:\n\t#   Point SSLCertificateChainFile at a file containing the\n\t#   concatenation of PEM encoded CA certificates which form the\n\t#   certificate chain for the server certificate. Alternatively\n\t#   the referenced file can be the same as SSLCertificateFile\n\t#   when the CA certificates are directly appended to the server\n\t#   certificate for convinience.\n\t#SSLCertificateChainFile /etc/apache2/ssl.crt/server-ca.crt\n\n\t#   Certificate Authority (CA):\n\t#   Set the CA certificate verification path where to find CA\n\t#   certificates for client authentication or alternatively one\n\t#   huge file containing all of them (file must be PEM encoded)\n\t#   Note: Inside SSLCACertificatePath you need hash symlinks\n\t#\t  to point to the certificate files. Use the provided\n\t#\t  Makefile to update the hash symlinks after changes.\n\t#SSLCACertificatePath /etc/ssl/certs/\n\t#SSLCACertificateFile /etc/apache2/ssl.crt/ca-bundle.crt\n\n\t#   Certificate Revocation Lists (CRL):\n\t#   Set the CA revocation path where to find CA CRLs for client\n\t#   authentication or alternatively one huge file containing all\n\t#   of them (file must be PEM encoded)\n\t#   Note: Inside SSLCARevocationPath you need hash symlinks\n\t#\t  to point to the certificate files. Use the provided\n\t#\t  Makefile to update the hash symlinks after changes.\n\t#SSLCARevocationPath /etc/apache2/ssl.crl/\n\t#SSLCARevocationFile /etc/apache2/ssl.crl/ca-bundle.crl\n\n\t#   Client Authentication (Type):\n\t#   Client certificate verification type and depth.  Types are\n\t#   none, optional, require and optional_no_ca.  Depth is a\n\t#   number which specifies how deeply to verify the certificate\n\t#   issuer chain before deciding the certificate is not valid.\n\t#SSLVerifyClient require\n\t#SSLVerifyDepth  10\n\n\t#   SSL Engine Options:\n\t#   Set various options for the SSL engine.\n\t#   o FakeBasicAuth:\n\t#    Translate the client X.509 into a Basic Authorisation.  This means that\n\t#    the standard Auth/DBMAuth methods can be used for access control.  The\n\t#    user name is the `one line\' version of the client\'s X.509 certificate.\n\t#    Note that no password is obtained from the user. Every entry in the user\n\t#    file needs this password: `xxj31ZMTZzkVA\'.\n\t#   o ExportCertData:\n\t#    This exports two additional environment variables: SSL_CLIENT_CERT and\n\t#    SSL_SERVER_CERT. These contain the PEM-encoded certificates of the\n\t#    server (always existing) and the client (only existing when client\n\t#    authentication is used). This can be used to import the certificates\n\t#    into CGI scripts.\n\t#   o StdEnvVars:\n\t#    This exports the standard SSL/TLS related `SSL_*\' environment variables.\n\t#    Per default this exportation is switched off for performance reasons,\n\t#    because the extraction step is an expensive operation and is usually\n\t#    useless for serving static content. So one usually enables the\n\t#    exportation for CGI and SSI requests only.\n\t#   o OptRenegotiate:\n\t#    This enables optimized SSL connection renegotiation handling when SSL\n\t#    directives are used in per-directory context.\n\t#SSLOptions +FakeBasicAuth +ExportCertData +StrictRequire\n\t<FilesMatch "\\.(?:cgi|shtml|phtml|php)$">\n\t\tSSLOptions +StdEnvVars\n\t</FilesMatch>\n\t<Directory /usr/lib/cgi-bin>\n\t\tSSLOptions +StdEnvVars\n\t</Directory>\n\n\t#   SSL Protocol Adjustments:\n\t#   The safe and default but still SSL/TLS standard compliant shutdown\n\t#   approach is that mod_ssl sends the close notify alert but doesn\'t wait for\n\t#   the close notify alert from client. When you need a different shutdown\n\t#   approach you can use one of the following variables:\n\t#   o ssl-unclean-shutdown:\n\t#    This forces an unclean shutdown when the connection is closed, i.e. no\n\t#    SSL close notify alert is send or allowed to received.  This violates\n\t#    the SSL/TLS standard but is needed for some brain-dead browsers. Use\n\t#    this when you receive I/O errors because of the standard approach where\n\t#    mod_ssl sends the close notify alert.\n\t#   o ssl-accurate-shutdown:\n\t#    This forces an accurate shutdown when the connection is closed, i.e. a\n\t#    SSL close notify alert is send and mod_ssl waits for the close notify\n\t#    alert of the client. This is 100% SSL/TLS standard compliant, but in\n\t#    practice often causes hanging connections with brain-dead browsers. Use\n\t#    this only for browsers where you know that their SSL implementation\n\t#    works correctly.\n\t#   Notice: Most problems of broken clients are also related to the HTTP\n\t#   keep-alive facility, so you usually additionally want to disable\n\t#   keep-alive for those clients, too. Use variable "nokeepalive" for this.\n\t#   Similarly, one has to force some clients to use HTTP/1.0 to workaround\n\t#   their broken HTTP/1.1 implementation. Use variables "downgrade-1.0" and\n\t#   "force-response-1.0" for this.\n\t# BrowserMatch "MSIE [2-6]" \\\n\t#\tnokeepalive ssl-unclean-shutdown \\\n\t#\tdowngrade-1.0 force-response-1.0\n\n</VirtualHost>\n'

export const DEBIAN_INDEX =
  '\n<!DOCTYPE html PUBLIC "-//W3C//DTD XHTML 1.0 Transitional//EN" "http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd">\n<html xmlns="http://www.w3.org/1999/xhtml">\n  <head>\n    <meta http-equiv="Content-Type" content="text/html; charset=UTF-8" />\n    <title>Apache2 Debian Default Page: It works</title>\n    <style type="text/css" media="screen">\n  * {\n    margin: 0px 0px 0px 0px;\n    padding: 0px 0px 0px 0px;\n  }\n\n  body, html {\n    padding: 3px 3px 3px 3px;\n\n    background-color: #D8DBE2;\n\n    font-family: Verdana, sans-serif;\n    font-size: 11pt;\n    text-align: center;\n  }\n\n  div.main_page {\n    position: relative;\n    display: table;\n\n    width: 800px;\n\n    margin-bottom: 3px;\n    margin-left: auto;\n    margin-right: auto;\n    padding: 0px 0px 0px 0px;\n\n    border-width: 2px;\n    border-color: #212738;\n    border-style: solid;\n\n    background-color: #FFFFFF;\n\n    text-align: center;\n  }\n\n  div.page_header {\n    height: 99px;\n    width: 100%;\n\n    background-color: #F5F6F7;\n  }\n\n  div.page_header span {\n    margin: 15px 0px 0px 50px;\n\n    font-size: 180%;\n    font-weight: bold;\n  }\n\n  div.page_header img {\n    margin: 3px 0px 0px 40px;\n\n    border: 0px 0px 0px;\n  }\n\n  div.table_of_contents {\n    clear: left;\n\n    min-width: 200px;\n\n    margin: 3px 3px 3px 3px;\n\n    background-color: #FFFFFF;\n\n    text-align: left;\n  }\n\n  div.table_of_contents_item {\n    clear: left;\n\n    width: 100%;\n\n    margin: 4px 0px 0px 0px;\n\n    background-color: #FFFFFF;\n\n    color: #000000;\n    text-align: left;\n  }\n\n  div.table_of_contents_item a {\n    margin: 6px 0px 0px 6px;\n  }\n\n  div.content_section {\n    margin: 3px 3px 3px 3px;\n\n    background-color: #FFFFFF;\n\n    text-align: left;\n  }\n\n  div.content_section_text {\n    padding: 4px 8px 4px 8px;\n\n    color: #000000;\n    font-size: 100%;\n  }\n\n  div.content_section_text pre {\n    margin: 8px 0px 8px 0px;\n    padding: 8px 8px 8px 8px;\n\n    border-width: 1px;\n    border-style: dotted;\n    border-color: #000000;\n\n    background-color: #F5F6F7;\n\n    font-style: italic;\n  }\n\n  div.content_section_text p {\n    margin-bottom: 6px;\n  }\n\n  div.content_section_text ul, div.content_section_text li {\n    padding: 4px 8px 4px 16px;\n  }\n\n  div.section_header {\n    padding: 3px 6px 3px 6px;\n\n    background-color: #8E9CB2;\n\n    color: #FFFFFF;\n    font-weight: bold;\n    font-size: 112%;\n    text-align: center;\n  }\n\n  div.section_header_red {\n    background-color: #CD214F;\n  }\n\n  div.section_header_grey {\n    background-color: #9F9386;\n  }\n\n  .floating_element {\n    position: relative;\n    float: left;\n  }\n\n  div.table_of_contents_item a,\n  div.content_section_text a {\n    text-decoration: none;\n    font-weight: bold;\n  }\n\n  div.table_of_contents_item a:link,\n  div.table_of_contents_item a:visited,\n  div.table_of_contents_item a:active {\n    color: #000000;\n  }\n\n  div.table_of_contents_item a:hover {\n    background-color: #000000;\n\n    color: #FFFFFF;\n  }\n\n  div.content_section_text a:link,\n  div.content_section_text a:visited,\n   div.content_section_text a:active {\n    background-color: #DCDFE6;\n\n    color: #000000;\n  }\n\n  div.content_section_text a:hover {\n    background-color: #000000;\n\n    color: #DCDFE6;\n  }\n\n  div.validator {\n  }\n    </style>\n  </head>\n  <body>\n    <div class="main_page">\n      <div class="page_header floating_element">\n        <img src="/icons/openlogo-75.png" alt="Debian Logo" class="floating_element"/>\n        <span class="floating_element">\n          Apache2 Debian Default Page\n        </span>\n      </div>\n<!--      <div class="table_of_contents floating_element">\n        <div class="section_header section_header_grey">\n          TABLE OF CONTENTS\n        </div>\n        <div class="table_of_contents_item floating_element">\n          <a href="#about">About</a>\n        </div>\n        <div class="table_of_contents_item floating_element">\n          <a href="#changes">Changes</a>\n        </div>\n        <div class="table_of_contents_item floating_element">\n          <a href="#scope">Scope</a>\n        </div>\n        <div class="table_of_contents_item floating_element">\n          <a href="#files">Config files</a>\n        </div>\n      </div>\n-->\n      <div class="content_section floating_element">\n\n\n        <div class="section_header section_header_red">\n          <div id="about"></div>\n          It works!\n        </div>\n        <div class="content_section_text">\n          <p>\n                This is the default welcome page used to test the correct \n                operation of the Apache2 server after installation on Debian systems.\n                If you can read this page, it means that the Apache HTTP server installed at\n                this site is working properly. You should <b>replace this file</b> (located at\n                <tt>/var/www/html/index.html</tt>) before continuing to operate your HTTP server.\n          </p>\n\n\n          <p>\n                If you are a normal user of this web site and don\'t know what this page is\n                about, this probably means that the site is currently unavailable due to\n                maintenance.\n                If the problem persists, please contact the site\'s administrator.\n          </p>\n\n        </div>\n        <div class="section_header">\n          <div id="changes"></div>\n                Configuration Overview\n        </div>\n        <div class="content_section_text">\n          <p>\n                Debian\'s Apache2 default configuration is different from the\n                upstream default configuration, and split into several files optimized for\n                interaction with Debian tools. The configuration system is\n                <b>fully documented in\n                /usr/share/doc/apache2/README.Debian.gz</b>. Refer to this for the full\n                documentation. Documentation for the web server itself can be\n                found by accessing the <a href="/manual">manual</a> if the <tt>apache2-doc</tt>\n                package was installed on this server.\n\n          </p>\n          <p>\n                The configuration layout for an Apache2 web server installation on Debian systems is as follows:\n          </p>\n          <pre>\n/etc/apache2/\n|-- apache2.conf\n|       `--  ports.conf\n|-- mods-enabled\n|       |-- *.load\n|       `-- *.conf\n|-- conf-enabled\n|       `-- *.conf\n|-- sites-enabled\n|       `-- *.conf\n          </pre>\n          <ul>\n                        <li>\n                           <tt>apache2.conf</tt> is the main configuration\n                           file. It puts the pieces together by including all remaining configuration\n                           files when starting up the web server.\n                        </li>\n\n                        <li>\n                           <tt>ports.conf</tt> is always included from the\n                           main configuration file. It is used to determine the listening ports for\n                           incoming connections, and this file can be customized anytime.\n                        </li>\n\n                        <li>\n                           Configuration files in the <tt>mods-enabled/</tt>,\n                           <tt>conf-enabled/</tt> and <tt>sites-enabled/</tt> directories contain\n                           particular configuration snippets which manage modules, global configuration\n                           fragments, or virtual host configurations, respectively.\n                        </li>\n\n                        <li>\n                           They are activated by symlinking available\n                           configuration files from their respective\n                           *-available/ counterparts. These should be managed\n                           by using our helpers\n                           <tt>\n                                a2enmod,\n                                a2dismod,\n                           </tt>\n                           <tt>\n                                a2ensite,\n                                a2dissite,\n                            </tt>\n                                and\n                           <tt>\n                                a2enconf,\n                                a2disconf\n                           </tt>. See their respective man pages for detailed information.\n                        </li>\n\n                        <li>\n                           The binary is called apache2. Due to the use of\n                           environment variables, in the default configuration, apache2 needs to be\n                           started/stopped with <tt>/etc/init.d/apache2</tt> or <tt>apache2ctl</tt>.\n                           <b>Calling <tt>/usr/bin/apache2</tt> directly will not work</b> with the\n                           default configuration.\n                        </li>\n          </ul>\n        </div>\n\n        <div class="section_header">\n            <div id="docroot"></div>\n                Document Roots\n        </div>\n\n        <div class="content_section_text">\n            <p>\n                By default, Debian does not allow access through the web browser to\n                <em>any</em> file apart of those located in <tt>/var/www</tt>,\n                <a href="http://httpd.apache.org/docs/2.4/mod/mod_userdir.html" rel="nofollow">public_html</a>\n                directories (when enabled) and <tt>/usr/share</tt> (for web\n                applications). If your site is using a web document root\n                located elsewhere (such as in <tt>/srv</tt>) you may need to whitelist your\n                document root directory in <tt>/etc/apache2/apache2.conf</tt>.\n            </p>\n            <p>\n                The default Debian document root is <tt>/var/www/html</tt>. You\n                can make your own virtual hosts under /var/www. This is different\n                to previous releases which provides better security out of the box.\n            </p>\n        </div>\n\n        <div class="section_header">\n          <div id="bugs"></div>\n                Reporting Problems\n        </div>\n        <div class="content_section_text">\n          <p>\n                Please use the <tt>reportbug</tt> tool to report bugs in the\n                Apache2 package with Debian. However, check <a\n                href="http://bugs.debian.org/cgi-bin/pkgreport.cgi?ordering=normal;archive=0;src=apache2;repeatmerged=0"\n                rel="nofollow">existing bug reports</a> before reporting a new bug.\n          </p>\n          <p>\n                Please report bugs specific to modules (such as PHP and others)\n                to respective packages, not to the web server itself.\n          </p>\n        </div>\n\n\n\n\n      </div>\n    </div>\n    <div class="validator">\n    </div>\n  </body>\n</html>\n\n'

